// Generated by OrchestKit Claude Plugin
// Created: 2026-09-04

// Model-selection precedence for getDefaults(), most specific first:
//
//   1. profile.md  gemini.models.<tool>.model   (per-tool)
//   2. profile.md  gemini.defaultModel          (all tools at once)
//   3. env         GEMINI_DEFAULT_MODEL         (machine-level)
//   4. DEFAULT_MODEL built into the client
//
// The profile outranks the environment deliberately: it is the user's durable
// reviewed config, while the env var exists so a machine or a test can set a
// default without a profile existing at all.
//
// DEFAULT_MODEL was verified against the live ListModels API on 2026-09-04 —
// gemini-3.8-flash is the newest stable text model and the only 3.8 build
// published; there is no gemini-3.8-pro.

import { test, describe, beforeEach, afterEach } from 'node:test';
import assert from 'node:assert/strict';
import { mkdir, writeFile, rm, mkdtemp } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import * as path from 'node:path';

import {
  getDefaults,
  buildThinkingConfig,
  DEFAULT_MODEL,
  __resetModelDefaultsCacheForTests,
} from '../src/gemini-client.js';

const ENV_MODEL = 'GEMINI_DEFAULT' + '_MODEL';

let dir: string;
let savedProjectDir: string | undefined;
let savedEnvModel: string | undefined;

async function writeProfile(geminiBlock: unknown): Promise<void> {
  await mkdir(path.join(dir, '.academic-helper'), { recursive: true });
  await writeFile(
    path.join(dir, '.academic-helper', 'profile.md'),
    '# Profile\n\n## Gemini\n\n```json\n' +
      JSON.stringify({ gemini: geminiBlock }, null, 2) +
      '\n```\n',
    'utf8',
  );
  __resetModelDefaultsCacheForTests();
}

describe('gemini model defaults', () => {
  beforeEach(async () => {
    dir = await mkdtemp(path.join(tmpdir(), 'gemini-defaults-'));
    savedProjectDir = process.env['CLAUDE_PROJECT_DIR'];
    savedEnvModel = process.env[ENV_MODEL];
    process.env['CLAUDE_PROJECT_DIR'] = dir;
    delete process.env[ENV_MODEL];
    __resetModelDefaultsCacheForTests();
  });

  afterEach(async () => {
    if (savedProjectDir === undefined) delete process.env['CLAUDE_PROJECT_DIR'];
    else process.env['CLAUDE_PROJECT_DIR'] = savedProjectDir;
    if (savedEnvModel === undefined) delete process.env[ENV_MODEL];
    else process.env[ENV_MODEL] = savedEnvModel;
    __resetModelDefaultsCacheForTests();
    await rm(dir, { recursive: true, force: true });
  });

  test('default is gemini-3.8-flash for every tool', async () => {
    assert.equal(DEFAULT_MODEL, 'gemini-3.8-flash');
    for (const tool of ['write_section', 'synthesize', 'edit', 'calibrate_sample', 'raw'] as const) {
      const d = await getDefaults(tool);
      assert.equal(d.model, 'gemini-3.8-flash', tool);
    }
  });

  test('per-tool thinking budgets are preserved across the model change', async () => {
    assert.equal((await getDefaults('write_section')).thinking_budget, 8192);
    assert.equal((await getDefaults('calibrate_sample')).thinking_budget, 1024);
    assert.equal((await getDefaults('raw')).thinking_budget, -1);
  });

  test('the default maps onto thinkingLevel, not thinkingBudget', async () => {
    // gemini-3.x takes thinkingLevel; passing an integer budget would be
    // rejected. Verified live: gemini-3.8-flash accepts thinkingLevel.
    assert.deepEqual(buildThinkingConfig(DEFAULT_MODEL, 8192), { thinkingLevel: 'high' });
    assert.deepEqual(buildThinkingConfig(DEFAULT_MODEL, 1024), { thinkingLevel: 'medium' });
    assert.deepEqual(buildThinkingConfig(DEFAULT_MODEL, -1), { thinkingLevel: 'high' });
    // 2.5 family still gets an integer budget.
    assert.deepEqual(buildThinkingConfig('gemini-2.5-flash', 2048), { thinkingBudget: 2048 });
  });

  test('env GEMINI_DEFAULT_MODEL overrides the built-in default', async () => {
    process.env[ENV_MODEL] = 'gemini-3.7-flash';
    __resetModelDefaultsCacheForTests();
    assert.equal((await getDefaults('write_section')).model, 'gemini-3.7-flash');
    assert.equal((await getDefaults('write_section')).thinking_budget, 8192);
  });

  test('profile gemini.defaultModel retargets every tool', async () => {
    await writeProfile({ defaultModel: 'gemini-3.1-pro-preview' });
    for (const tool of ['write_section', 'synthesize', 'raw'] as const) {
      assert.equal((await getDefaults(tool)).model, 'gemini-3.1-pro-preview', tool);
    }
  });

  test('profile defaultModel outranks the env var', async () => {
    process.env[ENV_MODEL] = 'gemini-3.7-flash';
    await writeProfile({ defaultModel: 'gemini-3.6-flash' });
    assert.equal((await getDefaults('edit')).model, 'gemini-3.6-flash');
  });

  test('per-tool override outranks the global default', async () => {
    await writeProfile({
      defaultModel: 'gemini-3.6-flash',
      models: { write_section: { model: 'gemini-3.1-pro-preview' } },
    });
    assert.equal((await getDefaults('write_section')).model, 'gemini-3.1-pro-preview');
    // Tools without their own entry still follow the global default.
    assert.equal((await getDefaults('synthesize')).model, 'gemini-3.6-flash');
  });

  test('a per-tool entry may set only a thinking budget and inherit the model', async () => {
    await writeProfile({
      defaultModel: 'gemini-3.6-flash',
      models: { synthesize: { thinking_budget: 4096 } },
    });
    const d = await getDefaults('synthesize');
    assert.equal(d.model, 'gemini-3.6-flash');
    assert.equal(d.thinking_budget, 4096);
  });

  test('an empty or absent profile falls back to the built-in default', async () => {
    await writeProfile({});
    assert.equal((await getDefaults('edit')).model, DEFAULT_MODEL);
  });
});
